',             'import com.fasterxml.jackson.annotation.JacksonInject;
import com.fasterxml.jackson.annotation.OptBoolean;
'         )      # Replace JavaScriptConfig injectable parameter annotation     txt2 = re.sub(         r'@JacksonInject\s+JavaScriptConfig\s+config',         r'@JacksonInject(useInput = OptBoolean.FALSE) JavaScriptConfig config',         txt     )      if txt2 == txt:         # Some files might have different whitespace (line breaks). Handle common newline split pattern.         txt2 = re.sub(             r'@JacksonInject\s*
